import forgelib as F
G = F.make(slug="the-forge-raven-cave", order=22, kw="crimson depths",
 title="How to Unlock Crimson Depths (Raven Cave) in The Forge",
 h1="How to Unlock the Crimson Depths (Raven Cave) in The Forge: Every Raven Quest",
 desc="How to unlock the Crimson Depths (Raven Cave) in The Forge: all three Raven quests and objectives, the Stolen Heart recipe, Raven armor and what's inside.",
 kw2=["the forge crimson depths","the forge raven quests","the forge raven cave","the forge stolen heart","the forge raven armor"],
 related=["the-forge-dragon-head-pickaxe","the-forge-island-3-guide","the-forge-armor-guide","the-forge-combat-guide"],
 ids=["taeQncP7cgQ","9l6FhNJgxiA"],
 lead="The Raven Cave Update (version 1.03) landed on January 3, 2026, and added a secret cave on Island 3. Fridge calls it the <strong>Crimson Depths</strong>, and the Forge Wiki lists it as the <strong>Raven Cave</strong>, \"the deeper you go, the less likely you are to return\". Here's every Raven quest you need to get in.",
 heading="Watch Fridge's Crimson Depths Videos",
 sections=[
 ("start","Starting the Raven Questline","""<p>Talk to the <strong>Raven</strong> on the Frostspire Expanse. The Forge Wiki says the questline asks you to bring different ores to unlock the Raven Cave and the sacred Raven armor. The whole line pays 10,500 XP and 65,000 Gold.</p>"""),
 ("quests","All Three Raven Quests","""<div class="table-wrap"><table><caption>Raven's Questline (Forge Wiki, November 11, 2026)</caption><thead><tr><th scope="col">Quest</th><th scope="col">Objectives</th><th scope="col">Reward</th></tr></thead><tbody>
<tr><td>Raven 1</td><td>Kill 5 Crystal Spiders, mine 10 Icy Pebbles, bring 1 Aetherit</td><td>2,500 XP, 12,500 Gold</td></tr>
<tr><td>Raven 2</td><td>Kill 10 Diamond Spiders and 1 Prismarine Spider, bring 1 Snowite</td><td>3,500 XP, 17,500 Gold</td></tr>
<tr><td>Raven 3</td><td>Kill 25 Mini Demonic Spiders, 10 Demonic Spiders and 1 Demonic Queen Spider, bring 1 Stolen Heart</td><td>4,500 XP, 35,000 Gold</td></tr></tbody></table></div>
<p>The Dragon Head Pickaxe cave opens after <strong>two of the three</strong> Raven quests. See our <a href="the-forge-dragon-head-pickaxe.html">Dragon Head Pickaxe guide</a>.</p>"""),
 ("ores","Getting the Quest Ores","""<ul><li><strong>Aetherit</strong> (Rare): mine it, or craft it from 1 Pumice and 2 Tungsten for 50 Gold.</li><li><strong>Snowite</strong> (Legendary): craft it from 1 Blue Crystal Ore, 2 Diamond and 3 Sapphire for 400 Gold.</li><li><strong>Stolen Heart</strong> (Divine): craft it from <strong>1 Arcane Crystal and 3 Golem Heart</strong> for 15,000 Gold. Golem Hearts drop from the Golem boss, and Arcane Crystal comes from the Goblin Cave or from crafting 3 Rainbow Crystals.</li></ul>
<p>Stolen Heart is the hard part, so start farming the Golem early. The gate opens at XX:00–XX:15 and XX:30–XX:45 each hour.</p>"""),
 ("inside","What's in the Raven Cave","""<p>Below the Raven Cave is <strong>Corruption's Heart</strong>, the source of the island's corruption and home of the Demonic Spiders. Fridge's Short calls the new cave a way to \"get super rich\", because its spiders and rocks feed the late-game crafting recipes. The questline also unlocks the <strong>Raven armor</strong> set:</p>
<div class="table-wrap"><table><caption>Raven armor (Forge Wiki)</caption><thead><tr><th scope="col">Piece</th><th scope="col">Health</th><th scope="col">Chance</th></tr></thead><tbody>
<tr><td>Raven's Helmet</td><td>+26.5%</td><td>1/8</td></tr><tr><td>Raven's Chestplate</td><td>+37%</td><td>1/8</td></tr><tr><td>Raven's Leggings</td><td>+29.25%</td><td>1/8</td></tr></tbody></table></div>
<p>Compare it with every other set in our <a href="the-forge-armor-guide.html">armor guide</a>.</p>""")],
 faq=[("How do you unlock the Crimson Depths in The Forge?","Complete the Raven's questline on the Frostspire Expanse. The Forge Wiki calls the area the Raven Cave."),
      ("How do you get a Stolen Heart in The Forge?","Craft it from 1 Arcane Crystal and 3 Golem Hearts for 15,000 Gold."),
      ("What does the Raven questline give?","10,500 XP, 65,000 Gold, access to the Raven Cave, and the Raven armor recipe.")],
 sources=[F.wiki("Raven%27s_Questline","Raven's Questline"),F.wiki("Raven_1","Raven 1–3 quests"),F.wiki("Crafting","Crafting recipes"),F.wiki("Armor"),F.wiki("Frostspire_Expanse","Frostspire Expanse"),F.wiki("Version_History","Version History")],
 howto=("How to unlock the Raven Cave in The Forge",[("Raven 1","Kill 5 Crystal Spiders, mine 10 Icy Pebbles and bring 1 Aetherit.","quests"),("Raven 2","Kill 10 Diamond Spiders and a Prismarine Spider, and bring 1 Snowite.","quests"),("Raven 3","Kill the Demonic Spiders and their Queen, and bring 1 Stolen Heart.","quests")]))
